s='''<!doctype html><html lang="fr"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marche Méga-Tsareena · aperçu amélioré</title><style>body{margin:0;font:16px system-ui;background:#111e18;color:#eef4e9}main{padding:24px;max-width:1120px;margin:auto}h1{font-size:clamp(24px,4vw,34px);margin:.3em 0}h2{font-size:18px;margin:.2em 0 .6em}.note{padding:14px;background:#443c28;border-left:4px solid #e6bc6b;line-height:1.5}.bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:20px 0}select,button{background:#d9edd1;color:#16261c;border:0;padding:10px;border-radius:7px;font:inherit;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#263b2e;padding:14px;border-radius:12px}canvas{width:100%;height:300px;display:block;background:#cbdcc1;image-rendering:pixelated}p{line-height:1.5}.caption{font-size:13px;color:#c8d8c8}.baseimg{width:auto;max-width:100%;height:250px;object-fit:contain;image-rendering:pixelated;display:block;margin:auto}.basebox{background:#cbdcc1;border-radius:8px;padding:10px;display:grid;place-items:center}.orig{margin-top:16px;max-width:350px}.links a{color:#d7f7c8}@media(max-width:800px){.grid{grid-template-columns:1fr}canvas{height:240px}}</style><main><h1>Marche en lévitation · aperçu amélioré</h1><p class="note">Les huit directions sont remplies, mais restent <strong>provisoires</strong>. Le nouveau rendu conserve plus de détails que l’ancien, à taille d’aperçu comparable. Profils et vues arrière à revoir ; bras fixes, mouvements approximatifs, offsets et ombres PMDO absents.</p><div class="bar"><label>Direction <select id="dir"><option value="0">Face</option><option value="1" selected>Avant-droite · modèle validé</option><option value="2">Profil droite</option><option value="3">Arrière-droite · miroir provisoire</option><option value="4">Dos</option><option value="5">Arrière-gauche</option><option value="6">Profil gauche · miroir provisoire</option><option value="7">Avant-gauche · modèle validé</option></select></label><button id="play">Pause</button><button id="next">Image suivante</button><span id="num"></span></div><div class="grid"><div class="card"><h2>Tsareena normale</h2><canvas id="normal" width="400" height="300"></canvas><p class="caption">Référence SpriteCollab</p></div><div class="card"><h2>Ancien aperçu</h2><canvas id="old" width="400" height="300"></canvas><p class="caption">Cellule 32 × 56 pixels</p></div><div class="card"><h2>Aperçu amélioré</h2><canvas id="new" width="400" height="300"></canvas><p class="caption">Cellule 64 × 112 pixels · détails mieux conservés</p></div></div><div class="orig" id="orig"><h2>Sprite de base approuvé</h2><div class="basebox"><img id="base" class="baseimg" alt="Sprite de base validé"></div><p class="caption">Original conservé, sans retouche.</p></div><p>Durées de référence : 8 / 10 / 8 / 10 ticks à 60 Hz. Les ombres de cet aperçu sont uniquement décoratives.</p><p class="links"><a href="__SHEET__" download="Walk-Anim-BROUILLON-64x112.png">Télécharger la planche améliorée (PNG transparent)</a></p><p class="caption">L’augmentation de résolution implique des cellules différentes de la référence : il faudra adapter les métadonnées et offsets avant toute intégration PMDO. Ce n’est pas un pack validé.</p></main><script>const data=__DATA__,img={};for(const k in data){img[k]=new Image;img[k].src=data[k]};let time=0,last=performance.now(),step=0,playing=true;const durations=[8,10,8,10];function current(t){let v=t*60/1000%36;for(let i=0;i<4;i++){if(v<durations[i])return i;v-=durations[i]}return 0}document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Reprendre';last=performance.now()};document.querySelector('#next').onclick=()=>{playing=false;step=(step+1)%4;document.querySelector('#play').textContent='Reprendre'};function draw(now){if(playing){time+=now-last;step=current(time)}last=now;let dir=+document.querySelector('#dir').value;document.querySelector('#num').textContent='Image '+(step+1)+' / 4';document.querySelector('#orig').style.display=dir===1||dir===7?'block':'none';if(dir===1||dir===7)document.querySelector('#base').src=data['base'+dir];for(const k of ['normal','old','new']){let c=document.querySelector('#'+k).getContext('2d');c.clearRect(0,0,400,300);c.fillStyle='rgba(25,43,29,.24)';c.beginPath();c.ellipse(200,260,47,8,0,0,2*Math.PI);c.fill();c.imageSmoothingEnabled=false;let w=k==='new'?64:32,h=k==='new'?112:56;if(img[k].complete&&img[k].naturalWidth)c.drawImage(img[k],step*w,dir*h,w,h,120,0,160,280)}requestAnimationFrame(draw)}requestAnimationFrame(draw)</script></html>'''.replace('__SHEET__',D['new']).replace('__DATA__',json.dumps(D));(p/'index.html').write_text(s,encoding='utf8')
